mapper.select:
SELECT id FROM tc_operation_audit
  WHERE tenant_id=#{tenant} AND resource_type='REFUND' AND resource_id=#{resource} AND action=#{action}
  ORDER BY id DESC LIMIT 1

mapper.sql:
FROM tc_operation_audit a
   LEFT JOIN tc_audit_operation_attempt r ON r.tenant_id=a.tenant_id AND r.id=a.audit_attempt_id
   WHERE a.tenant_id=#{tenant} AND a.resource_type='REFUND' AND a.resource_id=#{resource}

FROM tc_operation_audit a
   WHERE a.tenant_id=#{tenant}
   AND a.resource_type=#{query.filters.resourceType}
   AND a.resource_id=#{query.filters.resourceRef}
   AND a.created_at >= #{query.createdFrom} AND a.created_at < #{query.createdTo}

FROM tc_audit_attempt_outcome o
     JOIN tc_audit_operation_attempt r ON r.tenant_id=o.tenant_id AND r.id=o.attempt_id
     WHERE o.tenant_id=#{tenant} AND r.action_code IN ('refund.request','refund.approved','refund.rejected')
     AND o.resource_id=#{query.filters.resourceRef}
     AND o.recorded_at >= #{query.createdFrom} AND o.recorded_at < #{query.createdTo}

mapper.select:
SELECT CONCAT(origin,sequence_no) AS id,occurred_at,resource_type,resource_id,action,actor_id,result,error_code,trace_id FROM ( (SELECT 'E' AS origin,a.id AS sequence_no,a.created_at AS occurred_at,a.resource_type, a.resource_id,a.action,a.actor_key AS actor_id, CASE WHEN a.action='refund.approval.rejected-request' THEN 'REJECTED' ELSE 'RECORDED' END AS result, NULL AS error_code,a.audit_trace_id AS trace_id
AND a.created_at <= #{position.time}
AND (a.created_at < #{position.time} OR (a.created_at=#{position.time} AND a.id < #{position.id}))
ORDER BY a.created_at DESC,a.id DESC LIMIT #{scanLimit})
UNION ALL (SELECT 'R' AS origin,o.id AS sequence_no,o.recorded_at AS occurred_at,'REFUND' AS resource_type, o.resource_id,r.action_code AS action,r.actor_key AS actor_id,o.result_code AS result,o.error_code,r.trace_id
AND (o.recorded_at < #{position.time} OR (o.recorded_at=#{position.time} AND o.id < #{position.id}))
AND o.recorded_at < #{position.time}
ORDER BY o.recorded_at DESC,o.id DESC LIMIT #{scanLimit})
) page_rows ORDER BY occurred_at DESC,origin DESC,sequence_no DESC LIMIT #{limit} OFFSET #{offset}
